create or replace view public.registry_relationship_endpoint_work_queue with (security_invoker = true) as select u.relationship_id,u.missing_side,u.missing_entity_type,u.legacy_slug,u.relationship_type,u.relationship_role,u.source_entity_id,u.target_entity_id,count(a.canonical_artist_id)::integer as alias_match_count,min(a.canonical_artist_id::text)::uuid as alias_candidate_id,case when count(a.canonical_artist_id)=1 then 'ready_to_resolve' when count(a.canonical_artist_id)>1 then 'ambiguous_alias' else 'missing_entity' end as endpoint_work_state from public.registry_unresolved_relationship_endpoints u left join public.registry_artist_aliases a on u.missing_entity_type='artist' and a.alias_slug=u.legacy_slug and coalesce(a.status,'active')<>'rejected' group by u.relationship_id,u.missing_side,u.missing_entity_type,u.legacy_slug,u.relationship_type,u.relationship_role,u.source_entity_id,u.target_entity_id;;
